-- Hapus tabel lama jika sudah sempat dibuat sebelumnya
DROP TABLE IF EXISTS `links`;

-- 1. Buat Tabel links (Case-Sensitive untuk slug menggunakan utf8mb4_bin seperti Supabase)
CREATE TABLE `links` (
  `id` VARCHAR(36) NOT NULL,
  `created_at` DATETIME(6) DEFAULT CURRENT_TIMESTAMP(6),
  `url_asli` TEXT NOT NULL,
  `slug` VARCHAR(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `jumlah_klik` INT DEFAULT 0,
  `lembaga` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

